// Functional dependencies for the 1NF enrollment table (sets of attribute names)
const FDS = [
  [['student_id'], ['student_name']],
  [['course_code'], ['course_title', 'dept_code']],
  [['dept_code'], ['dept_name']],
  [['student_id', 'course_code'], ['instructor', 'grade']],
  [['instructor'], ['course_code']], // each instructor teaches exactly one course
];
const ALL = ['student_id', 'student_name', 'course_code', 'course_title',
  'dept_code', 'dept_name', 'instructor', 'grade'];

// Attribute closure X+: everything X determines (repeat until nothing new is added)
function closure(attrs, fds) {
  const result = new Set(attrs);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [lhs, rhs] of fds) {
      if (lhs.every((a) => result.has(a)) && rhs.some((a) => !result.has(a))) {
        rhs.forEach((a) => result.add(a));
        changed = true;
      }
    }
  }
  return result;
}
const isSuperkey = (attrs, rel, fds) => rel.every((a) => closure(attrs, fds).has(a));

// Find BCNF violations in a (sub-)relation. Simplified projection: it only tests the
// left-hand sides of the given FDs, which is enough for this example.
// a non-trivial X -> Y where X is not a superkey of that relation.
function bcnfViolations(rel, fds) {
  const out = [];
  for (const [lhs] of fds) {
    if (!lhs.every((a) => rel.includes(a))) continue;
    const implied = [...closure(lhs, fds)].filter((a) => rel.includes(a) && !lhs.includes(a));
    if (implied.length && !isSuperkey(lhs, rel, fds)) out.push(`${lhs.join(',')} -> ${implied.join(',')}`);
  }
  return out;
}

console.log('{student_id, course_code}+ =', [...closure(['student_id', 'course_code'], FDS)].length, 'of', ALL.length);
// {student_id, course_code}+ = 8 of 8   -> it is a key of the 1NF table
console.log('candidate key {student_id, instructor}?', isSuperkey(['student_id', 'instructor'], ALL, FDS));
// true   -> a second candidate key, via instructor -> course_code
console.log('1NF enrollment violations:', bcnfViolations(ALL, FDS));
// [ 'student_id -> student_name',
//   'course_code -> course_title,dept_code,dept_name',
//   'dept_code -> dept_name',
//   'instructor -> course_code,course_title,dept_code,dept_name' ]

const schemas = {
  student: ['student_id', 'student_name'],
  department: ['dept_code', 'dept_name'],
  course: ['course_code', 'course_title', 'dept_code'],
  enrollment3nf: ['student_id', 'course_code', 'instructor', 'grade'],
  teaching: ['instructor', 'course_code'],
  enrollmentBcnf: ['student_id', 'instructor', 'grade'],
};
for (const [name, rel] of Object.entries(schemas)) {
  const v = bcnfViolations(rel, FDS);
  console.log(name.padEnd(15), v.length ? `NOT BCNF: ${v.join('; ')}` : 'BCNF ok');
}
// student         BCNF ok
// department      BCNF ok
// course          BCNF ok
// enrollment3nf   NOT BCNF: instructor -> course_code
// teaching        BCNF ok
// enrollmentBcnf  BCNF ok

-- Final schema for the enrollment example (3NF tables + one BCNF-motivated split)
CREATE TABLE department (
  dept_code text PRIMARY KEY,                 -- natural key: short, stable, meaningful
  dept_name text NOT NULL UNIQUE
);
CREATE TABLE course (
  course_code  text PRIMARY KEY,
  course_title text NOT NULL,
  dept_code    text NOT NULL REFERENCES department (dept_code)
);
CREATE TABLE student (
  student_id   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,  -- surrogate key
  student_name text NOT NULL,
  email        text NOT NULL UNIQUE                              -- candidate key kept unique
);
CREATE TABLE student_phone (                  -- 1NF: one phone per row, not 'a, b'
  student_id bigint NOT NULL REFERENCES student (student_id) ON DELETE CASCADE,
  phone      text   NOT NULL,
  PRIMARY KEY (student_id, phone)
);
CREATE TABLE instructor (                     -- BCNF: instructor -> course lives here
  instructor_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name          text NOT NULL,
  course_code   text NOT NULL REFERENCES course (course_code),
  UNIQUE (instructor_id, course_code)         -- target for the composite FK below
);
CREATE TABLE enrollment (                     -- many-to-many junction with its own data
  student_id    bigint NOT NULL REFERENCES student (student_id),
  instructor_id bigint NOT NULL,
  course_code   text   NOT NULL,
  grade         text CHECK (grade IN ('A', 'B+', 'B', 'C', 'D', 'F')),
  PRIMARY KEY (student_id, course_code),      -- a student takes a course once
  FOREIGN KEY (instructor_id, course_code)    -- the instructor must teach that course
    REFERENCES instructor (instructor_id, course_code)
);

