-- Renaming a department is now a one-row update, no matter how many courses it has
UPDATE department SET dept_name = 'Computing' WHERE dept_code = 'CS';   -- UPDATE 1

-- Rejected: Dr. Lee (id 1) teaches CS101, not MA201
INSERT INTO enrollment VALUES (2, 1, 'MA201', 'A');
-- ERROR: insert or update on table "enrollment" violates foreign key constraint
--        "enrollment_instructor_id_course_code_fkey"

-- Rejected: Ana is already enrolled in CS101 (with Dr. Lee)
INSERT INTO enrollment VALUES (1, 2, 'CS101', 'B');
-- ERROR: duplicate key value violates unique constraint "enrollment_pkey"

-- Reassemble the original "spreadsheet" view with joins
SELECT s.student_name, c.course_code, d.dept_name, i.name AS instructor, e.grade
FROM enrollment e
JOIN student s    ON s.student_id = e.student_id
JOIN instructor i ON i.instructor_id = e.instructor_id
JOIN course c     ON c.course_code = e.course_code
JOIN department d ON d.dept_code = c.dept_code
ORDER BY s.student_name, c.course_code;
--  Ana | CS101 | Computing   | Dr. Lee  | A
--  Ana | MA201 | Mathematics | Dr. Kim  | B
--  Ben | CS101 | Computing   | Dr. Park | B+

-- Soft delete: keep the row, mark it deleted
CREATE TABLE account (
  id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email      text NOT NULL,
  deleted_at timestamptz                       -- NULL = live
);
-- Uniqueness must apply to LIVE rows only, or a deleted user blocks re-signup
CREATE UNIQUE INDEX account_email_live_uq ON account (email) WHERE deleted_at IS NULL;
-- Most queries want live rows: give them a view (and an index that matches)
CREATE VIEW live_account AS SELECT id, email FROM account WHERE deleted_at IS NULL;

INSERT INTO account (email) VALUES ('ana@example.com');
UPDATE account SET deleted_at = now() WHERE email = 'ana@example.com';
INSERT INTO account (email) VALUES ('ana@example.com');   -- OK: the old row is deleted
SELECT count(*) AS all_rows, (SELECT count(*) FROM live_account) AS live FROM account;
--  all_rows | live
--         2 |    1

-- JSONB: core fields as columns, sparse/variable attributes as a document
CREATE TABLE product (
  id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  sku        text NOT NULL UNIQUE,
  price      numeric(10,2) NOT NULL CHECK (price >= 0),  -- queried, constrained: a column
  attributes jsonb NOT NULL DEFAULT '{}'                  -- varies by category: a document
);
CREATE INDEX product_attributes_gin ON product USING gin (attributes jsonb_path_ops);

INSERT INTO product (sku, price, attributes) VALUES
  ('TSHIRT-M', 15.00, '{"size": "M", "color": "black", "material": "cotton"}'),
  ('LAPTOP-14', 1299.00, '{"ram_gb": 32, "cpu": "M4", "ports": ["usb-c", "hdmi"]}');

-- Containment query, served by the GIN index on large tables
SELECT sku, attributes->>'color' AS color FROM product WHERE attributes @> '{"color": "black"}';
--  TSHIRT-M | black

-- Typed extraction: ->> returns text, so cast before comparing numbers
SELECT sku FROM product WHERE (attributes->>'ram_gb')::int >= 16;
--  LAPTOP-14
